//! Runtime for Rust clients generated by
//! [openapi-generator-timvw-rust](https://github.com/timvw/openapi-generator-timvw-rust).
//!
//! A generated client sends every request through a [`Client`]: a [tower](https://docs.rs/tower) service from
//! [`http::Request<Body>`] to [`http::Response<Body>`]. By default that service is
//! [`reqwest`](https://docs.rs/reqwest) (feature `reqwest`, on by default), but any service will do: a hyper client,
//! a mock in tests, or reqwest wrapped in tower layers such as retries, timeouts and rate limits.
//!
//! ```no_run
//! # #[cfg(all(feature = "reqwest", feature = "retry"))]
//! # fn demo() {
//! use std::time::Duration;
//! use timvw_rust_runtime::{retry::RetryPolicy, Client};
//!
//! let client = Client::default()
//!     .layer(tower::timeout::TimeoutLayer::new(Duration::from_secs(30)))
//!     .layer(tower::retry::RetryLayer::new(RetryPolicy::default()));
//! # }
//! ```
//!
//! The generated code builds requests with [`RequestBuilder`] (the same methods as reqwest's builder) and reads
//! responses with [`Response`].
#![cfg_attr(docsrs, feature(doc_cfg))]

mod body;
mod client;
mod error;
pub mod multipart;
mod request;
#[cfg(feature = "reqwest")]
mod reqwest_service;
mod response;
#[cfg(feature = "retry")]
pub mod retry;

pub use body::Body;
pub use client::{Client, HttpService};
pub use error::Error;
pub use request::RequestBuilder;
#[cfg(feature = "reqwest")]
pub use reqwest_service::ReqwestService;
pub use response::Response;

pub use http;
pub use http::{header, HeaderMap, Method, StatusCode};
pub use tower;

/// The error type services and layers return: any error that can cross threads.
pub type BoxError = Box<dyn std::error::Error + Send + Sync>;
